description:
Implement a `useClickOutside` hook that accepts a `ref` and a `callback`. The callback fires whenever a `mousedown` event occurs outside the element the ref points to. The listener must be cleaned up on unmount.

**Example:**
```tsx
const ref = useRef(null);
useClickOutside(ref, () => setOpen(false));
return <div ref={ref}>...</div>;
```

starter_code:
import { useEffect, RefObject } from 'react';

export function useClickOutside(ref: RefObject<Element | null>, callback: () => void): void {
  // your code here
}

test_suite:
test('callback fires on click outside the element', () => {
  const div = document.createElement('div');
  document.body.appendChild(div);
  const ref = { current: div };
  const cb = vi.fn();
  renderHook(() => useClickOutside(ref, cb));
  act(() => document.dispatchEvent(new MouseEvent('mousedown', { bubbles: true })));
  expect(cb).toHaveBeenCalledTimes(1);
  document.body.removeChild(div);
});

test('callback does NOT fire for click inside the element', () => {
  const div = document.createElement('div');
  document.body.appendChild(div);
  const ref = { current: div };
  const cb = vi.fn();
  renderHook(() => useClickOutside(ref, cb));
  act(() => div.dispatchEvent(new MouseEvent('mousedown', { bubbles: true })));
  expect(cb).not.toHaveBeenCalled();
  document.body.removeChild(div);
});

test('listener removed on unmount', () => {
  const div = document.createElement('div');
  document.body.appendChild(div);
  const ref = { current: div };
  const cb = vi.fn();
  const { unmount } = renderHook(() => useClickOutside(ref, cb));
  unmount();
  act(() => document.dispatchEvent(new MouseEvent('mousedown', { bubbles: true })));
  expect(cb).not.toHaveBeenCalled();
  document.body.removeChild(div);
});

// __hidden__
test('callback always reflects latest reference', () => {
  const div = document.createElement('div');
  document.body.appendChild(div);
  const ref = { current: div };
  let calls = 0;
  const { rerender } = renderHook(({ cb }) => useClickOutside(ref, cb), {
    initialProps: { cb: () => { calls += 1; } }
  });
  rerender({ cb: () => { calls += 10; } });
  act(() => document.dispatchEvent(new MouseEvent('mousedown', { bubbles: true })));
  expect(calls).toBe(10);
  document.body.removeChild(div);
});

solution:
import { useEffect, useRef, RefObject } from 'react';

export function useClickOutside(ref: RefObject<Element | null>, callback: () => void): void {
  const savedCallback = useRef(callback);
  useEffect(() => { savedCallback.current = callback; });

  useEffect(() => {
    const handler = (event: MouseEvent) => {
      if (ref.current && !ref.current.contains(event.target as Node)) {
        savedCallback.current();
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [ref]);
}
